function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'teal' | 'amber' | 'red' | 'blue' }) {
  const tones = { neutral: 'bg-secondary text-muted-foreground', teal: 'bg-primary/10 text-primary', amber: 'bg-accent/20 text-foreground', red: 'bg-destructive/10 text-destructive', blue: 'bg-chart-3/10 text-chart-3' };
  return <span className={`inline-flex items-center gap-1 rounded-sm px-2 py-1 text-[10px] font-mono-ui font-medium uppercase tracking-[.08em] ${tones[tone]}`}>{children}</span>;
}

function Button({ children, onClick, variant = 'default', className = '', disabled = false }: { children: ReactNode; onClick?: () => void; variant?: 'default' | 'ghost' | 'accent'; className?: string; disabled?: boolean }) {
  const styles = { default: 'bg-primary text-primary-foreground hover:brightness-110', ghost: 'bg-transparent text-muted-foreground hover:bg-secondary hover:text-foreground', accent: 'bg-accent text-accent-foreground hover:brightness-105' };
  return <button data-testid="button-action" onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-sm px-3 py-2 text-xs font-semibold transition-all duration-200 active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`}>{children}</button>;
}
